{
  "overall_decision": "targeted_follow_up",
  "chapters": [
    {
      "chapter_id": "1B",
      "decision": "pass",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0004",
          "reason": "Indirect adviser quotation; useful only as context for the nuclear orbit, not as direct 2022 attribution to Khamenei."
        }
      ],
      "material_gaps": [],
      "reason": "Direct 2022 Khamenei statements and IAEA monitoring changes triangulate the nuclear record; the package preserves contrary evidence and does not overstate the adviser quote or inherited constitutional authority."
    },
    {
      "chapter_id": "2B",
      "decision": "pass",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0013",
          "reason": "Anonymous-sourced reconstruction of the Erbil motive; keep as context only because stronger direct strike evidence already exists."
        }
      ],
      "material_gaps": [],
      "reason": "The package shows repeated attributable coercion against Iraq and support for Russian drone use while preserving the defensive framing and attribution limits."
    },
    {
      "chapter_id": "3B",
      "decision": "pass",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0032",
          "reason": "Morality-police shutdown report was unconfirmed in the article and should be treated as contextual ambiguity rather than established relief."
        },
        {
          "evidence_id": "E0031",
          "reason": "Post-period 2024 synthesis of the protest wave; useful corroboration, but not contemporaneous 2022 evidence."
        }
      ],
      "material_gaps": [],
      "reason": "Multiple independent contemporaneous sources and the UN synthesis support the repression pattern, while the package distinguishes early allegations, later corroboration, and state-level attribution."
    },
    {
      "chapter_id": "4B",
      "decision": "pass",
      "remove_or_contextualize": [],
      "material_gaps": [],
      "reason": "The package fairly captures censorship, arrests, and internet restrictions with multiple source families and preserves the fact that many items are regime-level rather than direct personal orders."
    },
    {
      "chapter_id": "5B",
      "decision": "credible_gap",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0047",
          "reason": "Reuters summary of clerical thinking is indirect and does not show ruler-attributed implementation or outcome."
        },
        {
          "evidence_id": "E0048",
          "reason": "This is Raisi's budget approval, not a direct Khamenei decision; it should be treated as system context only."
        }
      ],
      "material_gaps": [
        {
          "gap": "Direct ruler-attributed implementation evidence for the 2022 economic program remains thin, especially on 5B.2, 5B.7, and 5B.9.",
          "lenses": ["5B.2", "5B.7", "5B.9"],
          "best_source_or_query_direction": "Primary budget-execution records, Central Bank decrees, or official 2022 policy documents tied to Khamenei's office",
          "why_it_matters": "Needed to move from slogans and macro context to attributable execution and correction."
        },
        {
          "gap": "Household and distribution outcome evidence is still mostly indirect.",
          "lenses": ["5B.8", "5B.10"],
          "best_source_or_query_direction": "Household survey data, poverty and consumption series, and provincial distribution evaluations",
          "why_it_matters": "Needed to tell whether the program changed ordinary lives, not only national aggregates."
        }
      ],
      "reason": "The package shows intent and macro pressure, but too much of the evidence is indirect system context; the line from Khamenei's 2022 directives to implementation and household outcomes is still too thin."
    },
    {
      "chapter_id": "6B",
      "decision": "pass",
      "remove_or_contextualize": [],
      "material_gaps": [],
      "reason": "The dossier balances direct 2022 interventions, structural service baselines, and persistent gaps in access and nutrition without collapsing system performance into personal credit."
    },
    {
      "chapter_id": "7B",
      "decision": "credible_gap",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0074",
          "reason": "Historical Setad reporting is inherited-structure context, not target-year 2022 conduct; it should not carry direct weight as 2022 personal integrity evidence."
        },
        {
          "evidence_id": "E0075",
          "reason": "Same inherited-background issue, and Reuters explicitly notes no proof of personal enrichment."
        }
      ],
      "material_gaps": [
        {
          "gap": "Direct 2022 personal-benefit evidence is thin.",
          "lenses": ["7B.3", "7B.4", "7B.5"],
          "best_source_or_query_direction": "Asset or gift records, procurement documents, sanctions findings on office-linked entities, or investigative reporting on family-linked networks",
          "why_it_matters": "Setad control is structural background, not proof of personal enrichment."
        },
        {
          "gap": "Direct 2022 correction and scrutiny evidence is limited.",
          "lenses": ["7B.2", "7B.6", "7B.7"],
          "best_source_or_query_direction": "Official transcripts, ethics or asset disclosures, court or audit records, or investigative findings on responses to criticism",
          "why_it_matters": "The package shows blame-shifting and censorship, but not a complete correction or accountability chain."
        }
      ],
      "reason": "The package captures blame-shifting and some concealment or network control, but the personal-benefit, appointment, and correction evidence for 2022 remains thin and leans on older structural material."
    },
    {
      "chapter_id": "8B",
      "decision": "pass",
      "remove_or_contextualize": [],
      "material_gaps": [],
      "reason": "The package identifies a clear 2022 program and multiple execution channels, and it keeps moral evaluation separate from competence while preserving mixed outcomes and adaptation."
    }
  ]
}
